'use strict';

// Boot-time sanity check: warn loudly if `public/bundle.js` is older than
// the source files it should have been built from.
//
// Why this exists: `public/bundle.js` is a build artefact — gitignored,
// regenerated by Browserify via `npm run build:js`. The bundle bakes in
// HTML strings from many template partials at build time (see
// `client/templates.js`). If you edit one of those partials but don't
// rebuild the bundle (or rebuild against a transient/reverted source —
// e.g. via `npm install` while a stash is active, a branch switch, a
// watcher firing on the wrong state), the bundle drifts from the source.
// Visitors then load an old version that doesn't include your change,
// and the breakage is invisible until someone happens to notice.
//
// This check fires once at server boot. It walks the source files
// referenced by `client/main.js` (transitively) and compares their
// mtimes to `public/bundle.js`'s mtime. Any source newer than the
// bundle is flagged. The warning is loud (boxed, ⚠ emoji) but does
// NOT exit — production deploys legitimately have build mtimes ≥
// source mtimes via `npm install` postinstall, so this is a no-op
// there. In dev it surfaces "you forgot to rebuild" before a user does.
//
// Trade-offs considered:
//   - We could checksum-compare baked template strings to detect drift
//     even when mtimes are equal. Stronger guarantee but ~50 lines and
//     fragile to whitespace/minification. Mtime gives 95% of the value
//     for a tenth of the code.
//   - We could rebuild automatically. Rejected: too magical, and a slow
//     rebuild on every `npm start` is annoying. Loud warning is enough.
//   - We could fail-fast (process.exit(1)). Rejected: too aggressive for
//     the prod case where mtimes might compare equal due to `tar`
//     extraction or filesystem precision quirks.

const fs = require('fs');
const path = require('path');

const BUNDLE_PATH = path.join(__dirname, '..', 'public', 'bundle.js');

// Source roots that get baked into bundle.js. If you add a new include
// pattern in client/templates.js or client/main.js, extend this list.
const SOURCE_ROOTS = [
  path.join(__dirname, '..', 'client'),
  path.join(__dirname, '..', 'templates', 'partials'),
  path.join(__dirname, '..', 'templates', 'helpers')
];

// Files we don't care about (test fixtures, README, etc.)
const IGNORE_RE = /\.(md|test\.js|spec\.js)$/;

function walk (dir, out) {
  let entries;
  try {
    entries = fs.readdirSync(dir, { withFileTypes: true });
  } catch (err) {
    return; // missing dir is fine — admin scaffolding may not exist in all branches
  }
  for (const entry of entries) {
    if (entry.name.startsWith('.')) continue;
    if (entry.name === 'node_modules') continue;
    const full = path.join(dir, entry.name);
    if (entry.isDirectory()) {
      walk(full, out);
    } else if (entry.isFile() && !IGNORE_RE.test(entry.name)) {
      out.push(full);
    }
  }
}

function checkBundleFreshness () {
  let bundleStat;
  try {
    bundleStat = fs.statSync(BUNDLE_PATH);
  } catch (err) {
    console.warn('\n⚠ public/bundle.js is missing. Run `npm run build:js` (or `npm run watch`) before serving.\n');
    return;
  }

  const sources = [];
  SOURCE_ROOTS.forEach(function (root) { walk(root, sources); });

  const newer = [];
  for (const src of sources) {
    try {
      const stat = fs.statSync(src);
      if (stat.mtimeMs > bundleStat.mtimeMs) {
        newer.push({
          path: path.relative(path.join(__dirname, '..'), src),
          ageDelta: Math.round((stat.mtimeMs - bundleStat.mtimeMs) / 1000)
        });
      }
    } catch (err) {
      // Skip files we can't stat — race condition with editor saves etc.
    }
  }

  if (newer.length === 0) return;

  // Show the worst offenders first; cap the list so a mass-format doesn't
  // produce a wall of text that itself drowns the warning.
  newer.sort(function (a, b) { return b.ageDelta - a.ageDelta; });
  const display = newer.slice(0, 8);
  const more = newer.length - display.length;

  const lines = [];
  lines.push('');
  lines.push('⚠  ──────────────────────────────────────────────────────────');
  lines.push('⚠  STALE CLIENT BUNDLE');
  lines.push('⚠  public/bundle.js is older than ' + newer.length + ' source file(s).');
  lines.push('⚠  Visitors may be loading outdated UI. Run:');
  lines.push('⚠      npm run build:js     (one-shot rebuild)');
  lines.push('⚠      npm run watch        (rebuild on changes)');
  lines.push('⚠');
  lines.push('⚠  Newer than bundle:');
  display.forEach(function (n) {
    lines.push('⚠    +' + n.ageDelta + 's  ' + n.path);
  });
  if (more > 0) lines.push('⚠    … and ' + more + ' more');
  lines.push('⚠  ──────────────────────────────────────────────────────────');
  lines.push('');
  console.warn(lines.join('\n'));
}

module.exports = checkBundleFreshness;
